"use client";

import { Canvas, useFrame } from "@react-three/fiber";
import { useMemo, useRef } from "react";
import * as THREE from "three";

/** Lightweight custom 3D fabric ribbon; decorative only, no product model implied. */
function SatinRibbon() {
  const ref = useRef<THREE.Mesh>(null);
  const geometry = useMemo(() => {
    const segments = 160;
    const vertices: number[] = [];
    const uvs: number[] = [];
    const indices: number[] = [];
    for (let i = 0; i <= segments; i++) {
      const t = (i / segments) * Math.PI * 2;
      const radius = 2.1 + 0.08 * Math.sin(t * 3);
      const center = new THREE.Vector3(
        radius * Math.cos(t),
        0.48 * Math.sin(t * 2.0),
        0.7 * Math.sin(t),
      );
      const widthVector = new THREE.Vector3(
        0.15 * Math.sin(t),
        0.24 * Math.cos(t * 1.5),
        0.38 * Math.cos(t),
      );
      const a = center.clone().add(widthVector);
      const b = center.clone().sub(widthVector);
      vertices.push(a.x, a.y, a.z, b.x, b.y, b.z);
      uvs.push(i / segments, 0, i / segments, 1);
      if (i < segments) {
        const k = i * 2;
        indices.push(k, k + 1, k + 2, k + 1, k + 3, k + 2);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
    g.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
    g.setIndex(indices);
    g.computeVertexNormals();
    return g;
  }, []);

  useFrame(({ clock }) => {
    if (ref.current) {
      const t = clock.getElapsedTime();
      ref.current.rotation.y = t * 0.12;
      ref.current.rotation.x = -0.35 + Math.sin(t * 0.35) * 0.08;
    }
  });

  return (
    <mesh ref={ref} geometry={geometry} rotation={[-0.35, 0, 0.1]}>
      <meshStandardMaterial
        color="#b40c21"
        metalness={0.25}
        roughness={0.31}
        side={THREE.DoubleSide}
      />
    </mesh>
  );
}

export default function RibbonScene() {
  return (
    <Canvas
      aria-hidden="true"
      dpr={[1, 1.5]}
      gl={{ alpha: true, antialias: true, powerPreference: "low-power" }}
      camera={{ position: [0, 0, 6], fov: 48 }}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      <ambientLight intensity={1.9} />
      <directionalLight position={[3, 6, 5]} intensity={3.8} color="#ffe3db" />
      <pointLight position={[-2, -1, 3]} intensity={1.8} color="#aa001e" />
      <SatinRibbon />
    </Canvas>
  );
}
